demo.css:
.sc { height: 150px; width: 260px; overflow: auto; border: 1px solid var(--demo-border); margin-top: 48px; }
.pad { height: 140px; }
.a { anchor-name: --btn; margin-left: 90px; font: 13px var(--demo-mono); }
.tip {
  position: absolute;
  position-anchor: --btn;
  position-area: top;
  position-visibility: anchor-visible;
  margin-bottom: 6px;
  padding: 4px 8px;
  background: var(--demo-accent); color: #0b1020;
  font: 12px var(--demo-sans);
}
